def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    # Compress all boundaries into elementary intervals [pts[i], pts[i+1] - 1].
    pts_set = {1, n + 1}
    for op in ops:
        pts_set.add(op[1])
        pts_set.add(op[2] + 1)
    pts = sorted(pts_set)
    idx = {p: i for i, p in enumerate(pts)}
    k = len(pts) - 1  # number of elementary intervals

    # Lazy tag per node is a function x -> max(0 if reset else x, v).
    # Blank cells are colour 0, and painting is max(old, c), so this covers both ops.
    size = 4 * k
    tv = [0] * size
    tr = [False] * size

    def apply(node, reset, v):
        if reset:
            tr[node] = True
            tv[node] = v
        else:
            if v > tv[node]:
                tv[node] = v

    def push(node):
        r, v = tr[node], tv[node]
        left, right = 2 * node, 2 * node + 1
        apply(left, r, v)
        apply(right, r, v)
        tr[node] = False
        tv[node] = 0

    def update(node, lo, hi, a, b, reset, v):
        if b < lo or hi < a:
            return
        if a <= lo and hi <= b:
            apply(node, reset, v)
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, a, b, reset, v)
        update(2 * node + 1, mid + 1, hi, a, b, reset, v)

    for op in ops:
        if op[0] == 1:
            _, l, r, c = op
            update(1, 0, k - 1, idx[l], idx[r + 1] - 1, False, c)
        else:
            _, l, r = op
            update(1, 0, k - 1, idx[l], idx[r + 1] - 1, True, 0)

    counts = {}

    def collect(node, lo, hi):
        if lo == hi:
            colour = tv[node]
            if colour > 0:
                length = pts[lo + 1] - pts[lo]
                counts[colour] = counts.get(colour, 0) + length
            return
        push(node)
        mid = (lo + hi) // 2
        collect(2 * node, lo, mid)
        collect(2 * node + 1, mid + 1, hi)

    collect(1, 0, k - 1)
    return [[c, counts[c]] for c in sorted(counts)]
